const OFFLINE_DELAY_MS = 3_000;

/**
 * Subscribes to a single Mercure presence topic and fires onStatusChange(status)
 * whenever the peer's presence changes. 'offline' updates are delayed by 3 s to
 * absorb tab reloads and quick reconnects.
 *
 * @param {string}   mercureUrl      URL generated by the Twig mercure() function
 * @param {Function} onStatusChange  (status: 'online'|'away'|'offline') => void
 */
export class PeerPresenceWatcher {
    #es            = null;
    #offlineTimer  = null;
    #onStatusChange;

    constructor(mercureUrl, onStatusChange) {
        this.#onStatusChange = onStatusChange;
        this.#connect(mercureUrl);
        window.addEventListener('pagehide', () => this.disconnect());
    }

    #connect(url) {
        this.#es = new EventSource(url, { withCredentials: true });
        this.#es.onmessage = (e) => this.#onMessage(e);
        this.#es.onerror   = () => {};
    }

    #onMessage(event) {
        let data;
        try { data = JSON.parse(event.data); } catch { return; }
        if (data.type !== 'presence') return;

        if (data.status === 'offline') {
            clearTimeout(this.#offlineTimer);
            this.#offlineTimer = setTimeout(() => {
                this.#offlineTimer = null;
                this.#onStatusChange('offline');
            }, OFFLINE_DELAY_MS);
        } else {
            clearTimeout(this.#offlineTimer);
            this.#offlineTimer = null;
            this.#onStatusChange(data.status);
        }
    }

    disconnect() {
        clearTimeout(this.#offlineTimer);
        this.#es?.close();
        this.#es = null;
    }
}
